class Solution {
    // 设 w 为 a[i] 的二进制最大长度
    // 返回一个长为 2^w 的数组 f，其中 f[S] 表示 a 中是 S 的子集的元素个数（把二进制数视作集合）
    // 时间复杂度 O(n + U log U)，其中 U = max(a)
    public int[] sosDP(int[] a) {
        int mx = 0;
        for (int x : a) {
            mx = Math.max(mx, x);
        }

        int w = 32 - Integer.numberOfLeadingZeros(mx); // 二进制长度上限
        int[] f = new int[1 << w];
        for (int x : a) {
            f[x]++; // 初始值
        }

        for (int i = 0; i < w; i++) {
            for (int s = 0; s < (1 << w); s++) {
                s |= 1 << i; // 优化：快速跳到 i 位是 1 的 s
                f[s] += f[s ^ (1 << i)];
            }
        }
        return f;
    }
}
